#include "dozi/core/MasteringRenderer.h"
#include "dozi/core/MasteringProcessorChain.h"
#include <sndfile.h>
#include <algorithm>
#include <system_error>
#include <stdexcept>
namespace dozi::core {
MasteringRenderResult MasteringRenderer::render(const std::filesystem::path&source,const std::filesystem::path&output,const MasteringPlan&plan,const CancellationToken&cancel,bool auditionMode,ProcessorTelemetryCallback telemetryCallback)const{
 MasteringAnalyzer analyzer;auto before=analyzer.analyse(source,cancel);if(!before.result)throw std::runtime_error(before.error?before.error->message:"Cancelled");
 SF_INFO info{};auto*in=sf_open(source.c_str(),SFM_READ,&info);if(!in)throw std::runtime_error(sf_strerror(nullptr));StereoAudioBuffer audio{info.samplerate,{},{}};std::vector<double>block(8192);sf_count_t frames;while((frames=sf_readf_double(in,block.data(),4096))>0){if(cancel.isCancelled()){sf_close(in);throw std::runtime_error("Cancelled");}for(sf_count_t i=0;i<frames;++i){audio.left.push_back(block[2*i]);audio.right.push_back(block[2*i+1]);}}sf_close(in);
 const auto stopped=[&cancel]{return cancel.isCancelled();};
 MasteringProcessorChain chain;chain.setPlan(plan);auto telemetry=chain.process(audio,auditionMode,std::move(telemetryCallback));double limiterMaximumGainReductionDb=0,limiterInputGainDb=0;bool activeLimiter=false;for(const auto&m:plan.modules)if(m.type==MasteringModuleType::truePeakLimiter){activeLimiter=!m.bypassed;if(const auto i=m.parameters.find("inputGainDb");i!=m.parameters.end())limiterInputGainDb=i->second;break;}for(const auto&t:telemetry)if(t.type==MasteringModuleType::truePeakLimiter)limiterMaximumGainReductionDb=t.maximumGainReductionDb;
 const auto temporary=std::filesystem::path(output.string()+".partial");std::filesystem::create_directories(output.parent_path());SF_INFO outInfo{};outInfo.samplerate=audio.sampleRate;outInfo.channels=2;outInfo.format=SF_FORMAT_WAV|SF_FORMAT_FLOAT;auto*out=sf_open(temporary.c_str(),SFM_WRITE,&outInfo);if(!out)throw std::runtime_error(sf_strerror(nullptr));std::vector<double>interleaved(8192);std::size_t written=0;while(written<audio.left.size()){if(stopped()){sf_close(out);std::filesystem::remove(temporary);throw std::runtime_error("Cancelled");}const auto frames=std::min<std::size_t>(4096,audio.left.size()-written);for(std::size_t i=0;i<frames;++i){interleaved[2*i]=audio.left[written+i];interleaved[2*i+1]=audio.right[written+i];}if(sf_writef_double(out,interleaved.data(),frames)!=static_cast<sf_count_t>(frames)){sf_close(out);std::filesystem::remove(temporary);throw std::runtime_error("Incomplete mastering export");}written+=frames;}sf_close(out);std::error_code ec;std::filesystem::rename(temporary,output,ec);if(ec){std::filesystem::remove(temporary);throw std::runtime_error("Atomic mastering commit failed");}
 auto after=analyzer.analyse(output,cancel);if(!after.result){std::filesystem::remove(output);throw std::runtime_error("Rendered master failed validation");}
 const auto signedLoudnessError=plan.targetIntegratedLufs-after.result->integratedLufs;
 if(activeLimiter&&std::abs(signedLoudnessError)>.25){auto adjustedPlan=plan;for(auto&module:adjustedPlan.modules)if(module.type==MasteringModuleType::truePeakLimiter&&!module.bypassed){const auto found=module.parameters.find("inputGainDb");const auto previous=found==module.parameters.end()?0.0:found->second;const auto adjusted=std::clamp(previous+std::clamp(signedLoudnessError,-3.0,3.0),-12.0,12.0);if(std::abs(adjusted-previous)>.05){module.parameters["inputGainDb"]=adjusted;std::filesystem::remove(output);return render(source,output,adjustedPlan,cancel,auditionMode,{});}break;}}
 if(activeLimiter&&after.result->truePeakDbtp>plan.truePeakCeilingDbtp+.05){std::filesystem::remove(output);throw std::runtime_error("Rendered master exceeds the selected true-peak ceiling");}
 if(activeLimiter&&after.result->clippedSampleCount>0){std::filesystem::remove(output);throw std::runtime_error("Rendered master contains clipped samples");}
 std::vector<std::string>warnings;const auto loudnessError=std::abs(signedLoudnessError);if(loudnessError>.5)warnings.push_back("Integrated loudness misses the selected target by "+std::to_string(loudnessError)+" LU; available limiter drive or headroom was exhausted");if(limiterMaximumGainReductionDb>6)warnings.push_back("Limiter gain reduction exceeds 6 dB; punch and distortion require critical listening");else if(limiterMaximumGainReductionDb>4)warnings.push_back("Limiter gain reduction exceeds 4 dB");if(after.result->phaseCorrelation<0)warnings.push_back("Negative output phase correlation requires mono-compatibility review");HealthScoreConfig hc;hc.targetLufs=plan.targetIntegratedLufs;hc.truePeakCeilingDbtp=plan.truePeakCeilingDbtp;MasteringHealthScorer scorer;return{output,*before.result,*after.result,scorer.score(*before.result,hc),scorer.score(*after.result,hc),limiterMaximumGainReductionDb,0,limiterInputGainDb,std::move(telemetry),std::move(warnings)};}
}
